#include <stdio.h>
#include <stdlib.h>

int** alloc_matrix(int rows, int cols) {
 int **m = malloc(rows * sizeof(int*));
 for (int i = 0; i < rows; i++)
 m[i] = malloc(cols * sizeof(int));
 return m;
}

void free_matrix(int **m, int rows) {
 for (int i = 0; i < rows; i++) free(m[i]);
 free(m);
}

int main() {
 int rows = 3, cols = 4;
 int **mat = alloc_matrix(rows, cols);
 for (int i = 0; i < rows; i++)
 for (int j = 0; j < cols; j++)
 mat[i][j] = i * cols + j;
 for (int i = 0; i < rows; i++) {
 for (int j = 0; j < cols; j++) printf("%3d", mat[i][j]);
 printf("\n");
 }
 free_matrix(mat, rows);
 return 0;
}

Key points: always free in reverse order of allocation. Each row is a separate heap block. Use valgrind to verify no leaks.

# TIMER decorator
import time, functools

def timer(func):
 @functools.wraps(func)
 def wrapper(*args, **kwargs):
 start = time.perf_counter()
 result = func(*args, **kwargs)
 print(f"{func.__name__} took {time.perf_counter()-start:.4f}s")
 return result
 return wrapper

# RETRY decorator with exponential backoff
def retry(max_attempts=3, exceptions=(Exception,), backoff=1.0):
 def decorator(func):
 @functools.wraps(func)
 def wrapper(*args, **kwargs):
 for attempt in range(1, max_attempts+1):
 try:
 return func(*args, **kwargs)
 except exceptions as e:
 if attempt == max_attempts:
 raise
 wait = backoff * (2 ** (attempt-1))
 print(f"Attempt {attempt} failed ({e}), retrying in {wait}s")
 time.sleep(wait)
 return wrapper
 return decorator

@retry(max_attempts=3, exceptions=(ConnectionError,))
def fetch_data(url):...

# AUTH decorator
def require_auth(roles=None):
 def decorator(func):
 @functools.wraps(func)
 def wrapper(request, *args, **kwargs):
 if not request.user or not request.user.is_authenticated:
 raise PermissionError("Not authenticated")
 if roles and not any(r in request.user.roles for r in roles):
 raise PermissionError(f"Requires role: {roles}")
 return func(request, *args, **kwargs)
 return wrapper
 return decorator

@require_auth(roles=["admin"])
def delete_user(request, user_id):...

# Metaclass: the class of a class. type is the default metaclass.
# class MyClass:... is equivalent to: MyClass = type('MyClass', (), {})

# SINGLETON metaclass
class SingletonMeta(type):
 _instances = {}
 def __call__(cls, *args, **kwargs):
 if cls not in cls._instances:
 cls._instances[cls] = super().__call__(*args, **kwargs)
 return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
 def __init__(self, url):
 self.url = url
 print(f"Connecting to {url}")

db1 = DatabaseConnection("postgresql://localhost/mydb")
db2 = DatabaseConnection("postgresql://localhost/other")
print(db1 is db2) # True - same instance, second __init__ not called

# REGISTRY metaclass - auto-registers all subclasses
class PluginMeta(type):
 registry = {}
 def __new__(mcs, name, bases, namespace):
 cls = super().__new__(mcs, name, bases, namespace)
 if bases: # skip the base class itself
 mcs.registry[name] = cls
 return cls

class Plugin(metaclass=PluginMeta): pass

class CSVPlugin(Plugin):
 def process(self, data): return data.split(',')

class JSONPlugin(Plugin):
 def process(self, data): import json; return json.loads(data)

print(PluginMeta.registry)
# {'CSVPlugin': <class CSVPlugin>, 'JSONPlugin': <class JSONPlugin>}

def get_plugin(name: str) -> Plugin:
 cls = PluginMeta.registry.get(name)
 if not cls: raise KeyError(f"Unknown plugin: {name}")
 return cls()

