#!/usr/bin/env bash
set -euo pipefail
IFS=$'\n\t'

# Script directory (reliable)
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Defaults
VERBOSE=false
DRY_RUN=false
CONFIG="${SCRIPT_DIR}/config.ini"
OUTPUT_DIR="/tmp/output"

usage() {
 cat <<EOF
Usage: $(basename "$0") [OPTIONS] <input_file>
 -c, --config FILE Config file (default: config.ini)
 -o, --output DIR Output directory (default: /tmp/output)
 -v, --verbose Enable verbose output
 -n, --dry-run Show what would be done without doing it
 -h, --help Show this help
EOF
 exit "${1:-0}"
}

# Parse arguments
while [[ $# -gt 0 ]]; do
 case "$1" in
 -c|--config) CONFIG="$2"; shift 2 ;;
 -o|--output) OUTPUT_DIR="$2"; shift 2 ;;
 -v|--verbose) VERBOSE=true; shift ;;
 -n|--dry-run) DRY_RUN=true; shift ;;
 -h|--help) usage 0 ;;
 --) shift; break ;;
 -*) echo "Unknown option: $1" >&2; usage 1 ;;
 *) break ;;
 esac
done

[[ $# -lt 1 ]] && { echo "Error: input file required" >&2; usage 1; }
INPUT="$1"

# Parse INI config file
declare -A CONFIG_MAP
parse_config() {
 local section=""
 while IFS='= ' read -r key value; do
 [[ "$key" == "#"* || -z "$key" ]] && continue
 [[ "$key" == "["* ]] && section="${key:1:-1}" && continue
 CONFIG_MAP["${section}.${key}"]="${value//\"}"
 done < "$1"
}
[[ -f "$CONFIG" ]] && parse_config "$CONFIG"

log() { $VERBOSE && echo "[$(date +%H:%M:%S)] $*" >&2; true; }
run() { $DRY_RUN && echo "DRY: $*" || "$@"; }

log "Input: $INPUT, Output: $OUTPUT_DIR"
run mkdir -p "$OUTPUT_DIR"
run cp "$INPUT" "$OUTPUT_DIR/"
echo "Done."

