import heapq

class PriorityQueue:
 def __init__(self):
 self._heap = []
 self._count = 0 # tie-breaker for equal priorities

 def push(self, priority, item):
 heapq.heappush(self._heap, (priority, self._count, item))
 self._count += 1

 def pop(self):
 return heapq.heappop(self._heap)[2]

 def peek(self):
 return self._heap[0][2]

 def empty(self):
 return len(self._heap) == 0

DIJKSTRA''S SHORTEST PATH:
def dijkstra(graph, start):
 """graph = {node: [(neighbour, weight),...]}"""
 dist = {node: float("inf") for node in graph}
 dist[start] = 0
 prev = {}
 pq = [(0, start)]

 while pq:
 d, u = heapq.heappop(pq)
 if d > dist[u]: continue # stale entry
 for v, weight in graph[u]:
 alt = dist[u] + weight
 if alt < dist[v]:
 dist[v] = alt
 prev[v] = u
 heapq.heappush(pq, (alt, v))

 return dist, prev

def shortest_path(prev, start, end):
 path = []
 node = end
 while node != start:
 path.append(node)
 node = prev.get(node)
 if node is None: return []
 path.append(start)
 return path[::-1]

# Example:
graph = {
 "A": [("B", 4), ("C", 2)],
 "B": [("D", 3), ("C", 1)],
 "C": [("B", 1), ("D", 5)],
 "D": []
}
dist, prev = dijkstra(graph, "A")
print(dist) # {"A": 0, "B": 3, "C": 2, "D": 6}
print(shortest_path(prev, "A", "D")) # ["A", "C", "B", "D"]
# Time: O((V + E) log V) with binary heap.

