// src/lib.rs
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
pub fn fibonacci(n: u32) -> u64 {
 if n <= 1 { return n as u64; }
 let (mut a, mut b) = (0u64, 1u64);
 for _ in 2..=n { let t = a+b; a=b; b=t; }
 b
}

#[wasm_bindgen]
pub fn process_image(data: &mut [u8], width: u32, height: u32) {
 // Operate on ImageData bytes directly. No copy from JS.
 for i in (0..data.len()).step_by(4) {
 let grey = (data[i] as u32 * 299 + data[i+1] as u32 * 587 + data[i+2] as u32 * 114) / 1000;
 data[i] = grey as u8; data[i+1] = grey as u8; data[i+2] = grey as u8;
 }
}
