GO CONCURRENCY — goroutines, channels, and select.

GOROUTINES — lightweight threads (2KB initial stack):
go func() { fmt.Println("I run concurrently") }()
// Spawn millions of goroutines. Runtime multiplexes onto OS threads (GOMAXPROCS).

CHANNELS — typed communication between goroutines:
ch := make(chan int) // unbuffered: send blocks until receive
ch := make(chan int, 100) // buffered: send blocks only when full

// Producer:
go func() { ch <- 42 }()

// Consumer:
val := <-ch
fmt.Println(val) // 42

close(ch) // signal no more values
for v := range ch { fmt.Println(v) } // receive until closed

WORKER POOL — classic pattern:
func workerPool(jobs <-chan int, results chan<- int, n int) {
 var wg sync.WaitGroup
 for i := 0; i < n; i++ {
 wg.Add(1)
 go func() {
 defer wg.Done()
 for job := range jobs { // range over channel until closed
 results <- process(job)
 }
 }()
 }
 go func() { wg.Wait(); close(results) }()
}

jobs := make(chan int, 100)
results := make(chan int, 100)
workerPool(jobs, results, 5)

