SELECT — multiplex channels:
func main() {
 ch1 := make(chan string)
 ch2 := make(chan string)
 timeout := time.After(5 * time.Second)

 go func() { time.Sleep(1 * time.Second); ch1 <- "one" }()
 go func() { time.Sleep(2 * time.Second); ch2 <- "two" }()

 for {
 select {
 case msg := <-ch1: fmt.Println("ch1:", msg)
 case msg := <-ch2: fmt.Println("ch2:", msg)
 case <-timeout: fmt.Println("timed out"); return
 default: fmt.Println("no message"); time.Sleep(100 * time.Millisecond)
 }
 }
}

